#!/usr/bin/env python3
"""Build Vridhi's central article index from published Article JSON-LD.

Existing editorial metadata is preserved. New pages are added only when they
contain valid Article/NewsArticle/BlogPosting structured data. No stories are
generated by this script.
"""
import json
import re
from pathlib import Path
from urllib.parse import urlparse

ROOT = Path(__file__).resolve().parents[2]
INDEX = ROOT / "articles.json"
BASE = "https://vridhi.ink/"
ARTICLE_TYPES = {"Article", "NewsArticle", "BlogPosting", "Report"}
SKIP_PARTS = {"briefs", "archive", "tag", "tags"}

def walk_jsonld(value):
    if isinstance(value, list):
        for item in value:
            yield from walk_jsonld(item)
    elif isinstance(value, dict):
        kind = value.get("@type", [])
        kinds = {kind} if isinstance(kind, str) else set(kind or [])
        if kinds & ARTICLE_TYPES:
            yield value
        for key in ("@graph", "mainEntity", "hasPart"):
            if key in value:
                yield from walk_jsonld(value[key])

def read_article(path):
    try:
        html = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return None
    scripts = re.findall(
        r'<script[^>]+type=["\']application/ld\+json["\'][^>]*>(.*?)</script>',
        html, flags=re.I | re.S
    )
    for raw in scripts:
        try:
            data = json.loads(raw.strip())
        except json.JSONDecodeError:
            continue
        for article in walk_jsonld(data):
            title = article.get("headline") or article.get("name")
            if not title:
                continue
            url = article.get("mainEntityOfPage") or article.get("url")
            if isinstance(url, dict):
                url = url.get("@id") or url.get("url")
            if not url:
                rel = path.parent.relative_to(ROOT).as_posix().strip("/")
                url = BASE + rel + "/"
            parsed = urlparse(url)
            if parsed.netloc and parsed.netloc != "vridhi.ink":
                continue
            if parsed.path:
                url = parsed.path.lstrip("/")
            image = article.get("image")
            if isinstance(image, list):
                image = image[0] if image else ""
            if isinstance(image, dict):
                image = image.get("url") or image.get("@id") or ""
            section = article.get("articleSection") or ""
            if isinstance(section, list):
                section = " ".join(str(x) for x in section)
            keywords = article.get("keywords") or []
            if isinstance(keywords, str):
                keywords = [x.strip() for x in keywords.split(",") if x.strip()]
            return {
                "title": str(title).strip(),
                "description": str(article.get("description") or "").strip(),
                "url": url.rstrip("/") + "/",
                "image": image or "",
                "published": article.get("datePublished") or "",
                "modified": article.get("dateModified") or article.get("datePublished") or "",
                "articleSection": section,
                "keywords": keywords,
            }
    return None

def infer_section(item, path):
    existing = item.get("section")
    if existing in {"Earth", "Discover", "Originals"}:
        return existing
    text = " ".join([
        str(item.get("title", "")), str(item.get("topic", "")),
        str(item.get("articleSection", "")), str(path)
    ]).lower()
    if "/originals/" in "/" + str(path) or "original investigation" in text or "vridhi original" in text:
        return "Originals"
    if any(word in text for word in ("environment", "groundwater", "water", "waste", "pollution", "climate", "biodiversity", "lake", "ecology")):
        return "Earth"
    return "Discover"

def infer_topic(item):
    if item.get("topic"):
        return item["topic"]
    keywords = item.get("keywords") or []
    return str(keywords[0]) if keywords else "Research"

try:
    current = json.loads(INDEX.read_text(encoding="utf-8"))
except (OSError, json.JSONDecodeError):
    current = {"version": 1, "articles": []}

items = current.get("articles") if isinstance(current.get("articles"), list) else []
by_url = {}
for item in items:
    url = str(item.get("url", "")).lstrip("/")
    if url:
        by_url[url.rstrip("/") + "/"] = dict(item)

# Scan only published article pages. Collection/landing pages without Article
# JSON-LD are ignored automatically.
for folder in ("journal", "originals"):
    base = ROOT / folder
    if not base.exists():
        continue
    for page in base.rglob("index.html"):
        rel = page.parent.relative_to(ROOT).as_posix()
        if any(part.lower() in SKIP_PARTS for part in Path(rel).parts):
            continue
        if rel in {"journal", "originals"}:
            continue
        found = read_article(page)
        if not found:
            continue
        url = found["url"]
        old = by_url.get(url, {})
        merged = dict(old)
        for key in ("title", "description", "image", "published", "modified"):
            if found.get(key):
                merged[key] = found[key]
        merged["url"] = url
        merged["section"] = infer_section({**found, **merged}, rel)
        merged["topic"] = infer_topic({**found, **merged})
        by_url[url] = merged

# Preserve known, manually curated records even if a page's schema is incomplete.
result = list(by_url.values())
result.sort(key=lambda item: item.get("published") or "", reverse=True)
payload = {
    "version": 2,
    "updated": __import__("datetime").date.today().isoformat(),
    "articles": result,
}
INDEX.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"Article index rebuilt: {len(result)} unique published articles.")
